define({"topics":[{"title":"Centering the dock and adjusting the dock hook tension","shortdesc":"<p class=\"shortdesc\">This dock adjustment procedure is required to properly align the cradle to the bridge in both the Z and X directions so that the cradle travels smoothly and protects table components from premature wear.<\/p>","href":"t_Dock-Centering-and-Dock-Hook-Tension-Adjustment_15868485.html","attributes":{"data-id":"id_13106536"},"menu":{"hasChildren":false},"tocID":"id_13106536-d46e10094","topics":[]},{"title":"Adjusting dock hardware","shortdesc":"<p class=\"shortdesc\">The Motor On actuation switch in the dock assembly should be adjusted so it is activated when the table Up foot pedal is pressed approximately three-fourths of its total length of travel.<\/p>","href":"t_Dock-Hardware-Adjustments_16503031.html","attributes":{"data-id":"id_15271092"},"menu":{"hasChildren":false},"tocID":"id_15271092-d46e10199","topics":[]}]});